from __future__ import annotations

from collections import defaultdict

from .base import AggregateMetric, GameContext, GameMetric
from .powerful_hand import second_own_turn_entries
from .trace_utils import (
    active,
    as_int,
    bench,
    candidate_index,
    cards,
    field_state,
    logs,
    normalized_evidence,
    option_attack_id,
    option_list,
    player_at,
    selected_attack_id,
    selected_options,
    trace_steps,
)


ABRA_CARD_ID = 741
ALAKAZAM_CARD_ID = 743
RARE_CANDY_CARD_ID = 1079

FAILURE_STAGES = (
    "rare_candy_not_played",
    "evolution_not_completed",
    "alakazam_not_active",
    "no_legal_attack",
    "attack_not_declared",
)


def _option_card_id(step: dict, physical_index: int, option: dict) -> int | None:
    for key in ("cardId", "card_id", "id"):
        value = as_int(option.get(key))
        if value is not None:
            return value
    if as_int(option.get("type")) != 7:
        return None
    hand_index = as_int(option.get("index"))
    hand = cards(player_at(step, physical_index), "hand")
    if hand_index is not None and 0 <= hand_index < len(hand):
        return as_int(hand[hand_index].get("id"))
    return None


def _field_cards(step: dict, physical_index: int) -> list[dict]:
    player = player_at(step, physical_index)
    return [card for card in [active(player), *bench(player)] if card]


def _selected_rare_candy(step: dict, physical_index: int) -> bool:
    return any(
        _option_card_id(step, physical_index, option) == RARE_CANDY_CARD_ID
        for option in selected_options(step)
    )


def _is_rare_candy_evolution(
    step: dict,
    physical_index: int,
    had_abra: bool,
    previous_field: dict[int, dict],
    previous_alakazam: int,
) -> tuple[bool, int | None]:
    log_evolution_found = False
    log_serial: int | None = None
    for log in logs(step):
        log_player = as_int(log.get("playerIndex"))
        if log_player is not None and log_player != physical_index:
            continue
        official_evolution = (
            as_int(log.get("type")) == 12
            and as_int(log.get("cardIdTarget")) == ABRA_CARD_ID
            and as_int(log.get("cardId")) == ALAKAZAM_CARD_ID
        )
        legacy_evolution = (
            as_int(log.get("cardIdBefore")) == ABRA_CARD_ID
            and as_int(log.get("cardIdAfter")) == ALAKAZAM_CARD_ID
        )
        if not official_evolution and not legacy_evolution:
            continue
        serial_key = "serial" if official_evolution else "serialAfter"
        serial = as_int(log.get(serial_key))
        previous = previous_field.get(serial) if serial is not None else None
        if previous is not None and as_int(previous.get("id")) == ALAKAZAM_CARD_ID:
            continue
        log_evolution_found = True
        log_serial = serial
        break

    field_cards = _field_cards(step, physical_index)
    alakazam = [
        card for card in field_cards if as_int(card.get("id")) == ALAKAZAM_CARD_ID
    ]
    for card in alakazam:
        serial = as_int(card.get("serial"))
        previous = previous_field.get(serial) if serial is not None else None
        if previous is not None and as_int(previous.get("id")) == ALAKAZAM_CARD_ID:
            continue
        evolved_from_abra = any(
            as_int(pre.get("id")) == ABRA_CARD_ID
            for pre in card.get("preEvolution") or []
            if isinstance(pre, dict)
        )
        if evolved_from_abra or (
            previous is not None and as_int(previous.get("id")) == ABRA_CARD_ID
        ):
            return True, serial

    if log_evolution_found:
        return True, log_serial
    if had_abra and len(alakazam) > previous_alakazam:
        new_serial = next(
            (
                as_int(card.get("serial"))
                for card in alakazam
                if as_int(card.get("serial")) not in previous_field
            ),
            None,
        )
        return True, new_serial
    return False, None


def _is_evolved_alakazam_active(
    step: dict,
    physical_index: int,
    evolved_serial: int | None,
) -> bool:
    active_card = active(player_at(step, physical_index))
    if active_card is None or as_int(active_card.get("id")) != ALAKAZAM_CARD_ID:
        return False
    return evolved_serial is None or as_int(active_card.get("serial")) == evolved_serial


def _source_evidence(
    trace: dict,
    context: GameContext,
    source: tuple[int, dict | None],
    failure_stage: str | None,
) -> tuple:
    evidence = normalized_evidence(
        trace,
        source[1],
        fallback_step=source[0],
        candidate_physical_index=context.candidate_physical_index,
    )
    evidence["failure_stage"] = failure_stage
    return (evidence,)


class RareCandyPlugin:
    metric_id = "rare_candy"

    def analyze_game(self, trace: dict, context: GameContext) -> GameMetric:
        entries = second_own_turn_entries(trace, context)
        physical_index = candidate_index(trace, context.candidate_physical_index)
        rare_position = next(
            (
                position
                for position, (_, step) in enumerate(entries)
                if _selected_rare_candy(step, physical_index)
            ),
            None,
        )
        failure_stage: str | None = None
        source: tuple[int, dict | None]

        if rare_position is None:
            failure_stage = "rare_candy_not_played"
            source = entries[-1] if entries else self._trace_fallback(trace)
        else:
            rare_source = entries[rare_position]
            before_cards = _field_cards(rare_source[1], physical_index)
            previous_field = field_state(rare_source[1], physical_index)
            had_abra = any(as_int(card.get("id")) == ABRA_CARD_ID for card in before_cards)
            previous_alakazam = sum(
                as_int(card.get("id")) == ALAKAZAM_CARD_ID for card in before_cards
            )
            evolution: tuple[int, int | None] | None = None
            for position in range(rare_position + 1, len(entries)):
                found, evolved_serial = _is_rare_candy_evolution(
                    entries[position][1],
                    physical_index,
                    had_abra,
                    previous_field,
                    previous_alakazam,
                )
                if found:
                    evolution = (position, evolved_serial)
                    break
            if evolution is None:
                failure_stage = "evolution_not_completed"
                source = entries[-1]
            else:
                evolved_position, evolved_serial = evolution
                active_position = next(
                    (
                        position
                        for position in range(evolved_position, len(entries))
                        if _is_evolved_alakazam_active(
                            entries[position][1],
                            physical_index,
                            evolved_serial,
                        )
                    ),
                    None,
                )
                if active_position is None:
                    failure_stage = "alakazam_not_active"
                    source = entries[evolved_position]
                else:
                    legal_positions = [
                        position
                        for position in range(active_position, len(entries))
                        if any(
                            option_attack_id(option) is not None
                            for option in option_list(entries[position][1])
                        )
                    ]
                    selected_position = next(
                        (
                            position
                            for position in legal_positions
                            if selected_attack_id(entries[position][1]) is not None
                        ),
                        None,
                    )
                    if selected_position is not None:
                        source = entries[selected_position]
                    elif legal_positions:
                        failure_stage = "attack_not_declared"
                        source = entries[legal_positions[0]]
                    else:
                        failure_stage = "no_legal_attack"
                        source = entries[active_position]

        success = failure_stage is None
        diagnostic = {
            "game_id": context.game_id,
            "opponent": context.opponent_name,
            "failure_stage": failure_stage,
        }
        return GameMetric(
            metric_id=self.metric_id,
            status="success" if success else "failure",
            numerator=int(success),
            denominator=1,
            value="success" if success else failure_stage,
            evidence=_source_evidence(trace, context, source, failure_stage),
            diagnostics=(diagnostic,),
        )

    @staticmethod
    def _trace_fallback(trace: dict) -> tuple[int, dict | None]:
        steps = trace_steps(trace)
        return (len(steps) - 1, steps[-1]) if steps else (0, None)

    def aggregate(self, results: list[GameMetric]) -> AggregateMetric:
        numerator = sum(result.numerator for result in results)
        denominator = sum(result.denominator for result in results)
        grouped: dict[str, dict[str, object]] = defaultdict(
            lambda: {"numerator": 0, "denominator": 0, "failure_stages": {}}
        )
        for result in results:
            diagnostic = result.diagnostics[0] if result.diagnostics else {}
            opponent = str(diagnostic.get("opponent", "unknown"))
            group = grouped[opponent]
            group["numerator"] = int(group["numerator"]) + result.numerator
            group["denominator"] = int(group["denominator"]) + result.denominator
            stage = diagnostic.get("failure_stage")
            if stage is not None:
                stages = group["failure_stages"]
                if isinstance(stages, dict):
                    stages[str(stage)] = int(stages.get(str(stage), 0)) + 1
        for group in grouped.values():
            attempts = int(group["denominator"])
            group["value"] = int(group["numerator"]) / attempts if attempts else None
        return AggregateMetric(
            metric_id=self.metric_id,
            numerator=numerator,
            denominator=denominator,
            value=numerator / denominator if denominator else None,
            by_opponent=dict(grouped),
        )

evaluation/metrics/registry.py:
from __future__ import annotations

from collections.abc import Iterable, Mapping
import html
import importlib
import importlib.util
import inspect
from pathlib import Path
import sys
from types import ModuleType
from uuid import uuid4

from .base import (
    AggregateMetric,
    GameContext,
    GameMetric,
    MetricPlugin,
    MetricPresentation,
)
from .correctness import CorrectnessPlugin
from .length import LengthPlugin
from .outcome import OutcomePlugin
from .powerful_hand import PowerfulHandPlugin
from .rare_candy import RareCandyPlugin
from .post_ko_relay import PostKORelayPlugin
from .run_away_draw import RunAwayDrawPlugin
from .library_pressure import LibraryPressurePlugin


CORE_PLUGIN_FACTORIES = {
    "outcome": OutcomePlugin,
    "length": LengthPlugin,
    "correctness": CorrectnessPlugin,
    "powerful_hand": PowerfulHandPlugin,
    "rare_candy": RareCandyPlugin,
    "post_ko_relay": PostKORelayPlugin,
    "run_away_draw": RunAwayDrawPlugin,
    "library_pressure": LibraryPressurePlugin,
}
CORE_METRIC_IDS = tuple(CORE_PLUGIN_FACTORIES)


class MetricRegistry:
    def __init__(
        self,
        plugins: Iterable[MetricPlugin] = (),
        *,
        trusted_plugins: Iterable[str] = (),
    ) -> None:
        self._plugins: dict[str, MetricPlugin] = {}
        self._trusted_plugins: dict[str, bool] = {}
        self._presentation_errors: tuple[dict[str, object], ...] = ()
        trusted_ids = set(trusted_plugins)
        for plugin in plugins:
            self.register(plugin, trusted=plugin.metric_id in trusted_ids)

    def register(self, plugin: MetricPlugin, *, trusted: bool = False) -> None:
        if plugin.metric_id in self._plugins:
            raise ValueError(f"metric already registered: {plugin.metric_id}")
        self._plugins[plugin.metric_id] = plugin
        self._trusted_plugins[plugin.metric_id] = trusted

    def get(self, metric_id: str) -> MetricPlugin:
        return self._plugins[metric_id]

    def analyze(self, trace: dict, context: GameContext) -> dict[str, GameMetric]:
        results: dict[str, GameMetric] = {}
        for metric_id, plugin in self._plugins.items():
            try:
                results[metric_id] = plugin.analyze_game(trace, context)
            except Exception as exc:
                results[metric_id] = GameMetric(
                    metric_id=metric_id,
                    status="error",
                    numerator=0,
                    denominator=1,
                    value="metric_error",
                    evidence=(),
                    diagnostics=(
                        {
                            "error": f"{type(exc).__name__}: {exc}",
                            "game_id": context.game_id,
                            "opponent": context.opponent_name,
                        },
                    ),
                    payload={
                        "games": 1,
                        "error_games": 1,
                        "unfinished_games": 0,
                        "lifecycle_status": "error",
                        "error_reasons": {type(exc).__name__: 1},
                        "exception_type": type(exc).__name__,
                    },
                )
        return results

    def aggregate(
        self,
        results: dict[str, list[GameMetric] | GameMetric],
    ) -> dict[str, AggregateMetric]:
        aggregates: dict[str, AggregateMetric] = {}
        for metric_id, metric_results in results.items():
            values = metric_results if isinstance(metric_results, list) else [metric_results]
            try:
                aggregates[metric_id] = self.get(metric_id).aggregate(values)
            except Exception as exc:
                attempts = len(values)
                input_unfinished_games = sum(
                    result.status == "unfinished" for result in values
                )
                aggregates[metric_id] = AggregateMetric(
                    metric_id=metric_id,
                    numerator=0,
                    denominator=attempts,
                    value="metric_error",
                    by_opponent={},
                    payload={
                        "games": attempts,
                        "error_count": 1,
                        "error_games": attempts,
                        "unfinished_games": input_unfinished_games,
                        "error_reasons": {type(exc).__name__: 1},
                        "exception_type": type(exc).__name__,
                        "error": f"{type(exc).__name__}: {exc}",
                    },
                )
        return aggregates

    def present(
        self,
        aggregates: Mapping[str, AggregateMetric],
        results: Mapping[str, list[GameMetric] | GameMetric],
    ) -> dict[str, MetricPresentation]:
        presentations: dict[str, MetricPresentation] = {}
        presentation_errors: list[dict[str, object]] = []
        for metric_id, aggregate in aggregates.items():
            plugin = self.get(metric_id)
            renderer = getattr(plugin, "render", None)
            metric_results = results.get(metric_id, ())
            values = metric_results if isinstance(metric_results, list) else [metric_results]
            try:
                if callable(renderer) and self._trusted_plugins.get(metric_id, False):
                    presentation = renderer(aggregate, tuple(values))
                    if not isinstance(presentation, MetricPresentation):
                        raise TypeError("metric render must return MetricPresentation")
                else:
                    presentation = generic_metric_presentation(aggregate)
            except Exception as exc:
                presentation_errors.append(
                    {
                        "metric_id": metric_id,
                        "error": f"{type(exc).__name__}: {exc}",
                    }
                )
                presentations[metric_id] = generic_metric_presentation(aggregate)
            else:
                presentations[metric_id] = presentation
        self._presentation_errors = tuple(presentation_errors)
        return presentations

    @property
    def presentation_errors(self) -> tuple[dict[str, object], ...]:
        return self._presentation_errors

    @property
    def plugins(self) -> tuple[MetricPlugin, ...]:
        return tuple(self._plugins.values())


def core_metric_plugins() -> tuple[MetricPlugin, ...]:
    """通过显式 factory 创建核心插件，保持 catalog 顺序稳定。"""
    return tuple(factory() for factory in CORE_PLUGIN_FACTORIES.values())


def generic_metric_presentation(aggregate: AggregateMetric) -> MetricPresentation:
    """为旧 plugin 提供不依赖专属 renderer 的稳定展示。"""
    metric_id = aggregate.metric_id
    title = f"指标：{metric_id}"
    markdown = "\n".join(
        (
            f"### {title}",
            "",
            "| 分子 | 分母 | value |",
            "| ---: | ---: | ---: |",
            "| "
            + " | ".join(
                _markdown_cell(value)
                for value in (
                    aggregate.numerator,
                    aggregate.denominator,
                    aggregate.value,
                )
            )
            + " |",
            "",
        )
    )
    html_id = html.escape(metric_id)
    html_numerator = html.escape(str(aggregate.numerator))
    html_denominator = html.escape(str(aggregate.denominator))
    html_value = html.escape(str(aggregate.value))
    html_fragment = (
        f'<section class="metric-plugin"><h3>{html_id}</h3>'
        '<table><thead><tr><th>分子</th><th>分母</th><th>value</th></tr></thead>'
        f"<tbody><tr><td>{html_numerator}</td><td>{html_denominator}</td>"
        f"<td>{html_value}</td></tr></tbody></table></section>"
    )
    return MetricPresentation(metric_id, title, markdown, html_fragment)


def _markdown_cell(value: object) -> str:
    return str(value).replace("|", "\\|").replace("\n", " ")


def _load_module(module_path: str | Path) -> tuple[ModuleType, str | None]:
    raw_path = str(module_path)
    class_name: str | None = None
    if ":" in raw_path and not Path(raw_path).is_file():
        raw_path, class_name = raw_path.rsplit(":", 1)
    path = Path(raw_path)
    if path.is_file():
        unique_name = f"evaluation_metric_plugin_{uuid4().hex}"
        spec = importlib.util.spec_from_file_location(unique_name, path)
        if spec is None or spec.loader is None:
            raise ValueError(f"cannot load metric module: {module_path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[unique_name] = module
        spec.loader.exec_module(module)
        return module, class_name
    return importlib.import_module(raw_path), class_name


def load_metric_plugin(module_path: str | Path) -> MetricPlugin:
    """加载一个额外 MetricPlugin；模块必须提供唯一的本地实现类。"""
    module, explicit_class = _load_module(module_path)
    if explicit_class:
        candidate = getattr(module, explicit_class, None)
        candidates = [candidate] if inspect.isclass(candidate) else []
    else:
        candidates = [
            value
            for value in vars(module).values()
            if inspect.isclass(value)
            and value.__module__ == module.__name__
            and isinstance(getattr(value, "metric_id", None), str)
            and callable(getattr(value, "analyze_game", None))
            and callable(getattr(value, "aggregate", None))
        ]
    if len(candidates) != 1:
        raise ValueError(
            f"metric module must expose exactly one plugin class: {module_path}"
        )
    try:
        plugin = candidates[0]()
    except TypeError as exc:
        raise ValueError("metric plugin class must have a no-argument factory") from exc
    if not isinstance(plugin, MetricPlugin):
        raise TypeError(f"metric plugin does not implement MetricPlugin: {module_path}")
    if not isinstance(plugin.metric_id, str) or not plugin.metric_id:
        raise ValueError("metric plugin metric_id must be a non-empty string")
    return plugin


def create_metric_registry(
    extra_module_paths: Iterable[str | Path] = (),
    profile_id: str = "core",
) -> MetricRegistry:
    """按 profile 创建 registry，并只追加额外插件，不允许覆盖已有 ID。"""
    from .profiles import get_metric_profile

    profile = get_metric_profile(profile_id)
    registry = MetricRegistry()
    for factory in profile.plugin_factories:
        registry.register(factory(), trusted=True)
    for module_path in extra_module_paths:
        plugin = load_metric_plugin(module_path)
        if plugin.metric_id in profile.metric_ids:
            reason = (
                "core metric"
                if plugin.metric_id in CORE_METRIC_IDS
                else "selected metric profile"
            )
            raise ValueError(
                f"dynamic plugin cannot override {reason}: {plugin.metric_id}"
            )
        registry.register(plugin, trusted=False)
    return registry


plugin_factory = load_metric_plugin

