from __future__ import annotations

from collections import defaultdict

from .base import AggregateMetric, GameContext, GameMetric
from .powerful_hand import _is_candidate_step
from .trace_utils import (
    active,
    as_int,
    bench,
    candidate_index,
    normalized_evidence,
    option_list,
    player_at,
    selected_options,
    trace_steps,
)


DUDUNSPARCE_CARD_ID = 66
RUN_AWAY_DRAW_OPTION_TYPE = 10


def _option_card_id(option: dict, step: dict, physical_index: int) -> int | None:
    for key in ("cardId", "card_id", "id"):
        card_id = as_int(option.get(key))
        if card_id is not None:
            return card_id
    area = as_int(option.get("area", option.get("inPlayArea")))
    if area != 4:
        return None
    active_card = active(player_at(step, physical_index))
    return as_int(active_card.get("id")) if active_card else None


def _is_run_away_draw(option: dict, step: dict, physical_index: int) -> bool:
    return (
        as_int(option.get("type")) == RUN_AWAY_DRAW_OPTION_TYPE
        and _option_card_id(option, step, physical_index) == DUDUNSPARCE_CARD_ID
    )


class RunAwayDrawPlugin:
    metric_id = "run_away_draw"

    def analyze_game(self, trace: dict, context: GameContext) -> GameMetric:
        physical_index = candidate_index(trace, context.candidate_physical_index)
        evidence: list[dict[str, object]] = []
        opportunities = 0
        for index, step in enumerate(trace_steps(trace)):
            if not _is_candidate_step(step, physical_index):
                continue
            player = player_at(step, physical_index)
            active_card = active(player)
            empty_bench = not bench(player)
            if (
                not active_card
                or as_int(active_card.get("id")) != DUDUNSPARCE_CARD_ID
                or not empty_bench
            ):
                continue
            if any(_is_run_away_draw(option, step, physical_index) for option in option_list(step)):
                opportunities += 1
            if not any(
                _is_run_away_draw(option, step, physical_index)
                for option in selected_options(step)
            ):
                continue
            source = normalized_evidence(
                trace,
                step,
                fallback_step=index,
                candidate_physical_index=context.candidate_physical_index,
            )
            source["empty_bench"] = True
            source["active_card_id"] = DUDUNSPARCE_CARD_ID
            evidence.append(source)

        if not evidence:
            steps = trace_steps(trace)
            evidence.append(
                normalized_evidence(
                    trace,
                    steps[-1] if steps else None,
                    fallback_step=len(steps) - 1 if steps else 0,
                    candidate_physical_index=context.candidate_physical_index,
                )
            )
        count = len(evidence) if evidence[0].get("empty_bench") is True else 0
        diagnostic = {
            "game_id": context.game_id,
            "opponent": context.opponent_name,
            "empty_bench_opportunities": opportunities,
            "empty_bench_run_away_draw_count": count,
        }
        return GameMetric(
            metric_id=self.metric_id,
            status="success",
            numerator=count,
            denominator=1,
            value=count,
            evidence=tuple(evidence),
            diagnostics=(diagnostic,),
        )

    def aggregate(self, results: list[GameMetric]) -> AggregateMetric:
        numerator = sum(result.numerator for result in results)
        denominator = sum(result.denominator for result in results)
        grouped: dict[str, dict[str, object]] = defaultdict(
            lambda: {"count": 0, "games": 0, "opportunities": 0}
        )
        for result in results:
            diagnostic = result.diagnostics[0] if result.diagnostics else {}
            opponent = str(diagnostic.get("opponent", "unknown"))
            group = grouped[opponent]
            group["count"] = int(group["count"]) + result.numerator
            group["games"] = int(group["games"]) + result.denominator
            group["opportunities"] = (
                int(group["opportunities"])
                + int(diagnostic.get("empty_bench_opportunities", 0))
            )
        for group in grouped.values():
            games = int(group["games"])
            group["value"] = int(group["count"]) / games if games else None
        return AggregateMetric(
            metric_id=self.metric_id,
            numerator=numerator,
            denominator=denominator,
            value=numerator / denominator if denominator else None,
            by_opponent=dict(grouped),
        )

evaluation/metrics/setup_relay.py:
from __future__ import annotations

from collections import defaultdict
from collections.abc import Iterable
import html

from .base import AggregateMetric, GameContext, GameMetric, MetricPresentation
from .powerful_hand import POWERFUL_HAND_ATTACK_ID, _is_candidate_step
from .trace_utils import (
    active,
    agent_turn_target,
    as_int,
    bench,
    current,
    logs,
    normalized_evidence,
    option_list,
    player_at,
    selected_attack_id,
    lifecycle_status,
    trace_steps,
)


ALAKAZAM = 743
ABRA = 741
DUNSPARCE = 305
DUDUNSPARCE = 66
RARE_CANDY = 1079
POKE_PAD = 1152
HILDA = 1225
DAWN = 1231
PSYCHIC_ENERGIES = {5, 19}
DRAW_LOG = 4
TURN_START_LOG = 2
OPENING_COMPONENT_KEYS = (
    "active_abra",
    "rare_candy",
    "alakazam_or_search",
    "psychic_energy_or_hilda",
    "all_four",
)


def _candidate_steps(trace: dict, physical_index: int) -> list[dict]:
    return [
        step
        for step in trace_steps(trace)
        if _is_candidate_step(step, physical_index)
    ]


def _card_ids(cards: object) -> set[int]:
    if not isinstance(cards, list):
        return set()
    return {
        card_id
        for card in cards
        if isinstance(card, dict)
        for card_id in [as_int(card.get("id"))]
        if card_id is not None
    }


def _snapshot(step: dict, physical_index: int) -> dict[str, object]:
    player = player_at(step, physical_index)
    active_card = active(player)
    field = [active_card, *bench(player)] if active_card else bench(player)
    return {
        "turn": as_int(current(step).get("turn")),
        "active_id": as_int(active_card.get("id")) if active_card else None,
        "active_serial": as_int(active_card.get("serial")) if active_card else None,
        "field_ids": _card_ids(field),
        "hand_ids": _card_ids(player.get("hand")),
        "discard_ids": _card_ids(player.get("discard")),
        "deck_count": as_int(player.get("deckCount"), 0) or 0,
    }


def _first_state(
    steps: list[dict], physical_index: int, first_turn: int
) -> tuple[int, dict] | None:
    candidates = [
        (index, step)
        for index, step in enumerate(steps)
        if as_int(current(step).get("turn")) == first_turn
    ]
    candidates.extend(
        (index, step)
        for index, step in enumerate(steps)
        if as_int(current(step).get("turn")) != first_turn
    )
    for index, step in candidates:
        snapshot = _snapshot(step, physical_index)
        if snapshot["active_id"] is not None:
            return index, snapshot
    return None


def _opening_components(snapshot: dict[str, object] | None) -> dict[str, bool]:
    if snapshot is None:
        return {key: False for key in OPENING_COMPONENT_KEYS}
    hand_ids = snapshot["hand_ids"]
    if not isinstance(hand_ids, set):
        hand_ids = set()
    components = {
        "active_abra": snapshot["active_id"] == ABRA,
        "rare_candy": RARE_CANDY in hand_ids,
        "alakazam_or_search": bool(hand_ids & {ALAKAZAM, POKE_PAD, HILDA, DAWN}),
        "psychic_energy_or_hilda": bool(hand_ids & (PSYCHIC_ENERGIES | {HILDA})),
    }
    components["all_four"] = all(components.values())
    return components


def _draws_to_second_turn(
    steps: list[dict], physical_index: int, first_turn: int, target_turn: int
) -> dict[str, object]:
    reached = False
    ability_draw_cards = 0
    normal_draw_cards = 0
    for step in steps:
        turn = as_int(current(step).get("turn"))
        if turn is None or turn < first_turn or turn > target_turn:
            continue
        if turn == target_turn:
            reached = True
        own_logs = [
            log for log in logs(step) if as_int(log.get("playerIndex")) == physical_index
        ]
        draws = sum(as_int(log.get("type")) == DRAW_LOG for log in own_logs)
        if any(as_int(log.get("type")) == TURN_START_LOG for log in own_logs):
            normal_draw_cards += draws
        else:
            ability_draw_cards += draws
    return {
        "reached_second_turn": reached,
        "ability_draw_cards": ability_draw_cards,
        "normal_draw_cards": normal_draw_cards,
        "total_draw_cards": ability_draw_cards + normal_draw_cards,
    }


class SetupRelayPlugin:
    metric_id = "setup_relay"

    def render(
        self, aggregate: AggregateMetric, results: tuple[GameMetric, ...]
    ) -> MetricPresentation:
        payload = aggregate.payload
        bridge = payload.get("dunsparce_bridge", {})
        draws = payload.get("second_turn_draws", {})
        bridge_values = bridge if isinstance(bridge, dict) else {}
        draw_values = draws if isinstance(draws, dict) else {}
        all_draws = draw_values.get("all_games", {})
        normal_draws = draw_values.get("normal_draw_cards", {})
        all_draw_values = all_draws if isinstance(all_draws, dict) else {}
        normal_draw_values = normal_draws if isinstance(normal_draws, dict) else {}
        numerator = bridge_values.get("numerator", 0)
        denominator = bridge_values.get("denominator", 0)
        ability_average = all_draw_values.get("average")
        normal_average = normal_draw_values.get("all_games", {})
        if not isinstance(normal_average, dict):
            normal_average = {}
        normal_average_value = normal_average.get("average")
        markdown = "\n".join(
            (
                "## Setup and relay",
                "",
                f"- bridge opportunities: {denominator}",
                f"- bridge completions: {numerator}",
                f"- ability draws / game: {ability_average}",
                f"- normal draws / game: {normal_average_value}",
                "",
            )
        )
        html_fragment = (
            '<section class="metric-plugin"><h2>Setup and relay</h2>'
            "<table><thead><tr><th>field</th><th>value</th></tr></thead><tbody>"
            f"<tr><td>bridge opportunities</td><td>{html.escape(str(denominator))}</td></tr>"
            f"<tr><td>bridge completions</td><td>{html.escape(str(numerator))}</td></tr>"
            f"<tr><td>second-turn draws</td><td>{html.escape(str(ability_average))}</td></tr>"
            f"<tr><td>normal draws</td><td>{html.escape(str(normal_average_value))}</td></tr>"
            "</tbody></table></section>"
        )
        return MetricPresentation(self.metric_id, "Setup and relay", markdown, html_fragment)

    def analyze_game(self, trace: dict, context: GameContext) -> GameMetric:
        lifecycle = lifecycle_status(trace)
        physical_index = context.candidate_physical_index
        first_turn = 1 if context.candidate_first else 2
        target_turn = agent_turn_target(trace, physical_index) or (
            3 if context.candidate_first else 4
        )
        steps = _candidate_steps(trace, physical_index)
        first_state_entry = _first_state(steps, physical_index, first_turn)
        first_state = first_state_entry[1] if first_state_entry else None
        target_steps = [
            step for step in steps if as_int(current(step).get("turn")) == target_turn
        ]
        reached = bool(target_steps)
        target_state = _snapshot(target_steps[0], physical_index) if target_steps else None
        attack_success = any(
            selected_attack_id(step) == POWERFUL_HAND_ATTACK_ID for step in target_steps
        )
        saw_dudunsparce = any(
            DUDUNSPARCE in _snapshot(step, physical_index)["field_ids"]
            for step in steps
            if (as_int(current(step).get("turn")) or 0) <= target_turn
        )
        bridge_opportunity = bool(
            first_state
            and first_state["active_id"] == DUNSPARCE
        )
        bridge_completed = bool(
            bridge_opportunity
            and saw_dudunsparce
            and target_state
            and target_state["active_id"] == ALAKAZAM
            and attack_success
        )
        components = _opening_components(first_state)
        draws = _draws_to_second_turn(steps, physical_index, first_turn, target_turn)
        payload = {
            "opening_components": components,
            "all_four": components["all_four"],
            "bridge_opportunity": bridge_opportunity,
            "bridge_completed": bridge_completed,
            "draws_to_second_turn": draws,
            "target_turn": target_turn,
            "reached_second_turn": reached,
            "attack_success": attack_success,
            "evidence_strength": "proxy" if bridge_completed else "observed",
            "games": 1,
            "error_games": int(lifecycle == "error"),
            "unfinished_games": int(lifecycle == "unfinished"),
            "lifecycle_status": lifecycle,
        }
        evidence_step = target_steps[0] if target_steps else (steps[-1] if steps else None)
        evidence_index = (
            trace_steps(trace).index(evidence_step) if evidence_step in trace_steps(trace) else 0
        )
        evidence = normalized_evidence(
            trace,
            evidence_step,
            fallback_step=evidence_index,
            candidate_physical_index=physical_index,
        )
        evidence.update({"bridge_opportunity": bridge_opportunity, "bridge_completed": bridge_completed})
        return GameMetric(
            metric_id=self.metric_id,
            status=(
                "error"
                if lifecycle == "error"
                else "unavailable"
                if lifecycle == "unfinished"
                else "success"
                if reached
                else "unavailable"
            ),
            numerator=int(attack_success),
            denominator=1,
            value="attack_selected" if attack_success else "not_selected",
            evidence=(evidence,),
            diagnostics=(
                {
                    "game_id": context.game_id,
                    "opponent": context.opponent_name,
                    "turn_order": "first" if context.candidate_first else "second",
                    "candidate_first": context.candidate_first,
                },
            ),
            payload=payload,
        )

    def aggregate(self, results: list[GameMetric]) -> AggregateMetric:
        values = list(results)
        numerator = sum(result.numerator for result in values)
        denominator = sum(result.denominator for result in values)
        by_turn_order = {
            turn_order: _aggregate_group(
                result
                for result in values
                if result.diagnostics
                and isinstance(result.diagnostics[0], dict)
                and result.diagnostics[0].get("turn_order") == turn_order
            )
            for turn_order in ("first", "second")
        }
        components = {
            key: sum(
                bool(result.payload.get("opening_components", {}).get(key))
                for result in values
                if isinstance(result.payload.get("opening_components"), dict)
            )
            for key in OPENING_COMPONENT_KEYS
        }
        error_games = sum(
            int(result.payload.get("error_games", result.status == "error"))
            for result in values
        )
        unfinished_games = sum(
            int(result.payload.get("unfinished_games", result.status == "unfinished"))
            for result in values
        )
        return AggregateMetric(
            metric_id=self.metric_id,
            numerator=numerator,
            denominator=denominator,
            value=numerator / denominator if denominator else None,
            by_opponent=_by_opponent(values),
            payload={
                "games": len(values),
                "error_games": error_games,
                "unfinished_games": unfinished_games,
                "all_games": _aggregate_group(values),
                "by_turn_order": by_turn_order,
                "opening_four_components": {
                    "component_counts": components,
                    "sample_games": len(values),
                },
                "dunsparce_bridge": {
                    "numerator": sum(bool(result.payload.get("bridge_completed")) for result in values),
                    "denominator": sum(bool(result.payload.get("bridge_opportunity")) for result in values),
                },
                "second_turn_draws": _draw_aggregate(values),
            },
        )


def _aggregate_group(results: Iterable[GameMetric]) -> dict[str, object]:
    values = list(results)
    attack = sum(result.numerator for result in values)
    opportunities = sum(bool(result.payload.get("bridge_opportunity")) for result in values)
    successes = sum(bool(result.payload.get("bridge_completed")) for result in values)
    error_games = sum(
        int(result.payload.get("error_games", result.status == "error"))
        for result in values
    )
    unfinished_games = sum(
        int(result.payload.get("unfinished_games", result.status == "unfinished"))
        for result in values
    )
    return {
        "games": len(values),
        "error_games": error_games,
        "unfinished_games": unfinished_games,
        "attack_numerator": attack,
        "attack_denominator": len(values),
        "attack_rate": attack / len(values) if values else None,
        "bridge_opportunities": opportunities,
        "bridge_successes": successes,
        "bridge_rate": successes / opportunities if opportunities else None,
    }


def _draw_average(results: list[GameMetric], field: str, *, reached_only: bool = False) -> dict[str, object]:
    values = [
        result
        for result in results
        if not reached_only or result.payload.get("draws_to_second_turn", {}).get("reached_second_turn")
    ]
    total = sum(
        int(result.payload.get("draws_to_second_turn", {}).get(field, 0))
        for result in values
    )
    return {"total": total, "games": len(values), "average": total / len(values) if values else None}


def _draw_aggregate(results: list[GameMetric]) -> dict[str, object]:
    return {
        "all_games": _draw_average(results, "ability_draw_cards"),
        "reached_second_turn": _draw_average(results, "ability_draw_cards", reached_only=True),
        "first": _draw_average(
            [result for result in results if result.diagnostics and result.diagnostics[0].get("turn_order") == "first"],
            "ability_draw_cards",
        ),
        "second": _draw_average(
            [result for result in results if result.diagnostics and result.diagnostics[0].get("turn_order") == "second"],
            "ability_draw_cards",
        ),
        "normal_draw_cards": {
            "all_games": _draw_average(results, "normal_draw_cards"),
            "reached_second_turn": _draw_average(results, "normal_draw_cards", reached_only=True),
            "first": _draw_average(
                [result for result in results if result.diagnostics and result.diagnostics[0].get("turn_order") == "first"],
                "normal_draw_cards",
            ),
            "second": _draw_average(
                [result for result in results if result.diagnostics and result.diagnostics[0].get("turn_order") == "second"],
                "normal_draw_cards",
            ),
        },
    }


def _by_opponent(results: Iterable[GameMetric]) -> dict[str, dict[str, object]]:
    grouped: dict[str, list[GameMetric]] = defaultdict(list)
    for result in results:
        diagnostic = result.diagnostics[0] if result.diagnostics else {}
        opponent = str(diagnostic.get("opponent", "unknown")) if isinstance(diagnostic, dict) else "unknown"
        grouped[opponent].append(result)
    return {opponent: _aggregate_group(values) for opponent, values in grouped.items()}

evaluation/metrics/trace_utils.py:
from __future__ import annotations

from typing import Any


def terminal_result(trace: dict) -> dict:
    """返回 worker trace 中嵌套的终态对局结果。"""
    value = trace.get("result")
    return value if isinstance(value, dict) else {}


def result_field(trace: dict, name: str, default: Any = None) -> Any:
    """优先读取嵌套终态字段，兼容历史扁平 fixture。"""
    result = terminal_result(trace)
    if name in result:
        return result[name]
    return trace.get(name, default)


def lifecycle_status(trace: dict) -> str:
    """把 worker 终态归一为 finished、unfinished 或 error。"""
    error_kind = str(result_field(trace, "error_kind", "") or "").lower()
    status = str(result_field(trace, "status", "") or "").lower()
    unfinished_values = {"step_limit", "step limit", "unfinished"}
    if error_kind in unfinished_values or status in unfinished_values:
        return "unfinished"
    if error_kind:
        return "error"
    if status and status not in {"finished", "success"}:
        return "error"
    if result_field(trace, "finished") is False:
        return "unfinished"
    return "finished"


def as_int(value: Any, default: int | None = None) -> int | None:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value.strip())
        except ValueError:
            return default
    return default


def observation(step: dict) -> dict:
    value = step.get("observation")
    return value if isinstance(value, dict) else {}


def current(step: dict) -> dict:
    value = observation(step).get("current")
    if isinstance(value, dict):
        return value
    return {
        "turn": step.get("turn", 0),
        "yourIndex": step.get("yourIndex", 0),
        "players": step.get("players") or [],
    }


def players(step: dict) -> list[dict]:
    value = current(step).get("players")
    return value if isinstance(value, list) else []


def player_at(step: dict, index: int) -> dict:
    values = players(step)
    if 0 <= index < len(values) and isinstance(values[index], dict):
        return values[index]
    return {}


def cards(player: dict, area: str) -> list[dict]:
    values = player.get(area) or []
    return [value for value in values if isinstance(value, dict)]


def active(player: dict) -> dict | None:
    values = cards(player, "active")
    return values[0] if values else None


def bench(player: dict) -> list[dict]:
    return cards(player, "bench")


def option_list(step: dict) -> list[dict]:
    select = step.get("select")
    if not isinstance(select, dict):
        select = observation(step).get("select")
    if not isinstance(select, dict):
        return []
    values = select.get("options")
    if values is None:
        values = select.get("option")
    return [value for value in values or [] if isinstance(value, dict)]


def action_list(step: dict) -> list[int]:
    values = step.get("action")
    if not isinstance(values, list):
        return []
    return [value for value in values if isinstance(value, int) and not isinstance(value, bool)]


def selected_options(step: dict) -> list[dict]:
    options = option_list(step)
    return [
        options[index]
        for index in action_list(step)
        if 0 <= index < len(options)
    ]


def option_attack_id(option: dict) -> int | None:
    return as_int(option.get("attackId", option.get("attack_id")))


def selected_attack_id(step: dict) -> int | None:
    for option in selected_options(step):
        value = option_attack_id(option)
        if value is not None:
            return value
    return None


def logs(step: dict) -> list[dict]:
    values = observation(step).get("logs")
    return values if isinstance(values, list) else []


def field_state(step: dict, player_index: int) -> dict[int, dict]:
    state: dict[int, dict] = {}
    player = player_at(step, player_index)
    for pokemon in [active(player), *bench(player)]:
        if not pokemon:
            continue
        serial = as_int(pokemon.get("serial"))
        if serial is not None:
            state[serial] = pokemon
    return state


def hp_loss_serials(step: dict, player_index: int) -> set[int]:
    return {
        serial
        for log in logs(step)
        if isinstance(log, dict)
        and as_int(log.get("type")) == 16
        and as_int(log.get("playerIndex")) == player_index
        and (
            log.get("putDamageCounter") is True
            or (as_int(log.get("value"), 0) or 0) < 0
        )
        for serial in [as_int(log.get("serial"))]
        if serial is not None
    }


def _moved_from_field_to_discard(log: dict, player_index: int, serial: int) -> bool:
    return (
        as_int(log.get("type")) == 6
        and as_int(log.get("playerIndex")) == player_index
        and as_int(log.get("serial")) == serial
        and as_int(log.get("fromArea")) in {4, 5}
        and as_int(log.get("toArea")) == 3
    )


def knockout_is_confirmed(
    step: dict,
    log: dict,
    player_index: int,
    previous_field: dict[int, dict],
) -> bool:
    serial = as_int(log.get("serial"))
    if serial is None:
        return False
    previous = previous_field.get(serial)
    previous_hp = as_int(previous.get("hp")) if previous is not None else None
    if previous_hp is not None and previous_hp <= 0:
        return True
    current_card = field_state(step, player_index).get(serial)
    current_hp = as_int(current_card.get("hp")) if current_card is not None else None
    if current_hp is not None and current_hp <= 0:
        return True
    return serial in hp_loss_serials(step, player_index) and any(
        _moved_from_field_to_discard(candidate, player_index, serial)
        for candidate in logs(step)
        if isinstance(candidate, dict)
    )


def trace_steps(trace: dict) -> list[dict]:
    values = trace.get("trace")
    return values if isinstance(values, list) else []


def result_steps(trace: dict) -> int | None:
    """读取 worker 的 action 选择次数，兼容历史扁平 trace。"""
    result = terminal_result(trace)
    values = (result.get("steps"), trace.get("steps"))
    for value in values:
        count = as_int(value)
        if count is not None and count >= 0:
            return count
    return None


def candidate_index(trace: dict, context_index: int = 0) -> int:
    for field in ("candidate_physical_index", "candidatePhysicalIndex", "alakazamPhysicalIndex"):
        value = as_int(result_field(trace, field))
        if value in (0, 1):
            return value
    return context_index


def normalized_evidence(
    trace: dict,
    step: dict | None,
    *,
    fallback_step: int,
    candidate_physical_index: int = 0,
    default_role: str = "trace",
) -> dict[str, Any]:
    """标准化 worker 和历史 trace 的最小证据定位字段。"""
    raw_step = step if isinstance(step, dict) else {}
    state = raw_step.get("state")
    state = state if isinstance(state, dict) else {}
    state_current = state.get("current")
    state_current = state_current if isinstance(state_current, dict) else state
    observed_current = observation(raw_step).get("current")
    observed_current = observed_current if isinstance(observed_current, dict) else {}
    sources = (observed_current, state_current, raw_step)

    def read(name: str, default: Any = None) -> Any:
        for source in sources:
            if name in source and source[name] is not None:
                return source[name]
        return default

    role = raw_step.get("role")
    if not role:
        role = read("role")
    if not role:
        current_player = as_int(read("yourIndex"))
        candidate = candidate_index(trace, candidate_physical_index)
        if current_player in (0, 1):
            role = "candidate" if current_player == candidate else "opponent"
        else:
            role = default_role

    return {
        "step": read("step", fallback_step),
        "turn": read("turn", 0),
        "role": role,
        "action": raw_step.get("action", []),
    }


def agent_turn_target(trace: dict, candidate_physical_index: int | None = None) -> int | None:
    candidate = candidate_index(trace, candidate_physical_index or 0)
    for step in trace_steps(trace):
        first_player = as_int(current(step).get("firstPlayer"))
        if first_player in (0, 1):
            return 3 if first_player == candidate else 4
    return None


def is_agent_step(step: dict, agent_label: str | None = None) -> bool:
    if agent_label is None:
        return step.get("role") not in {"opponent", "finished"}
    return step.get("role") == agent_label


# 兼容旧 evaluator helper 的内部命名；这些别名仍然只处理传入的 JSON dict。
_observation = observation
_current = current
_players = players
_player_at = player_at
_active = active
_bench = bench
_option_list = option_list
_action_list = action_list
_selected_options = selected_options
_selected_attack_id = selected_attack_id
_field_state = field_state
_knockout_is_confirmed = knockout_is_confirmed
_agent_turn_target = agent_turn_target
_is_agent_step = is_agent_step

